function traceStop()
{
   trace("JWP STOPPED");
}
function destroy()
{
   trace("mat destroy");
   SHELL.removeListener(SHELL.PLAYER_MOVE_DONE,Delegate.create(this,handlePlayerStop));
   SHELL.removeListener(SHELL.ROOM_DESTROYED,Delegate.create(this,destroy));
}
function handlePlayerStop(penguin)
{
   trace("handlePlayerStop in mat");
   if(penguin.player_id != currentPlayer.player_id)
   {
      return undefined;
   }
   var _loc1_ = "game_ninja";
   if(item.triggers_mc.hitTest(penguin.x,penguin.y,true))
   {
      if(SHELL.joinGameFromIglooStatus)
      {
         trace("SHELL.joinGameFromIglooStatus: " + SHELL.joinGameFromIglooStatus);
         return undefined;
      }
      trace("THIS ITEM WADDLE ID " + _THIS.item.waddle_id);
      if(playerHasCards)
      {
         SHELL.addCookie(SHELL.GAME_COOKIE,_loc1_,{mode:1});
         SHELL.addCookie(SHELL.GAME_COOKIE,_loc1_,{room:ROOM_STRING});
         SHELL.setJoinGameFromIgloo(true,ROOM_STRING);
         trace("HSF _THIS = " + _THIS);
         trace("HSF _THIS.waddle_id = " + _THIS.item.waddle_id);
         ENGINE.sendJoinCJWaddle("card",_THIS.item.waddle_id,true,2,true);
      }
      else
      {
         trace("ELSE IS CALLED IN ITEM");
         INTERFACE.showPrompt("ok",SHELL.getLocalizedString("starter_deck_prompt"));
      }
   }
}
item.seat_frames = [7,1];
item.seat0._visible = false;
item.seat1._visible = false;
trace("CREATING MAT");
var ENGINE = _global.getCurrentEngine();
var SHELL = _global.getCurrentShell();
var INTERFACE = _global.getCurrentInterface();
var currentPlayer = SHELL.getMyPlayerObject();
var CARDS_ITEM = 821;
var ROOM_STRING = String(SHELL.getCurrentRoomId() - 1000);
var playerHasCards;
playerHasCards = SHELL.isItemInMyInventory(CARDS_ITEM);
item.triggers_mc._visible = false;
item.art.cards._visible = false;
var rolledOver = false;
this.onEnterFrame = function()
{
   if(item.hitTest(_root._xmouse,_root._ymouse,true))
   {
      if(!rolledOver)
      {
         rolledOver = true;
         trace("mat roll over..");
         trace("SHELL: " + SHELL);
         item.art.cards._visible = true;
         item.art.gotoAndStop(2);
         INTERFACE.showHint(this,"w.app.hint.cj");
      }
   }
   else if(rolledOver)
   {
      rolledOver = false;
      item.art.cards._visible = false;
      item.art.gotoAndStop(1);
      INTERFACE.closeHint();
   }
};
trace("adding listeners for SHELL.PLAYER_MOVE_DONE: ");
SHELL.addListener(SHELL.PLAYER_MOVE_DONE,handlePlayerStop);
SHELL.addListener(SHELL.ROOM_DESTROYED,destroy);
SHELL.addListener(SHELL.PLAYER_MOVE_DONE,traceStop);
var _THIS = this;
stop();
